using AppCondominio.Modules.Maintenance.Infrastructure;
using Microsoft.Extensions.Diagnostics.HealthChecks;
namespace AppCondominio.Api.Health;
public sealed class MaintenanceDatabaseHealthCheck(MaintenanceDbContext dbContext):IHealthCheck{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken cancellationToken=default){try{return await dbContext.Database.CanConnectAsync(cancellationToken)?HealthCheckResult.Healthy("Maintenance SQL Server is reachable."):HealthCheckResult.Unhealthy("Maintenance SQL Server is not reachable.");}catch(Exception ex){return HealthCheckResult.Unhealthy("Maintenance SQL Server readiness check failed.",ex);}}}